def solve(A):
    h,w=len(A),len(A[0])
    cnt=Counter(v for r in A for v in r)
    f=cnt.most_common(1)[0][0]; l=cnt.most_common(2)[1][0]
    marks=[[1 if A[r][c] not in (f,l) else 0 for c in range(w)] for r in range(h)]
    rlist=[r for r in range(h) if any(marks[r])]; clist=[c for c in range(w) if any(marks[r][c] for r in range(h))]
    def gaps(idx): return [(a,b) for a,b in zip(idx,idx[1:])]
    rg=gaps(rlist); cg=gaps(clist)
    out=[]
    for ra,rb in rg:
        row=[]
        for ca,cb in cg:
            vals={(ra,ca),(ra,cb),(rb,ca),(rb,cb)}
            cs={A[r][c] for r,c in vals}
            c=f
            cand=(cs-{f})
            if len(cand)==1 and all(A[r][c]==next(iter(cand)) for r,c in vals):
                c=next(iter(cand))
            row.append(c)
        out.append(row)
    return out
for p in ('1','2','3'):
    A=G[f'Demo pair {p} input']; B=G[f'Demo pair {p} output']
    o=solve(A)
    print(p, o==B)
    if o!=B: print(o,'\n',B)
